// 模糊搜：中文语义 / 中文关键词 / 英文图标名，返回图标名数组
export function xhIconSearch(q, limit = 60) {
  const s = String(q || "").trim().toLowerCase();
  if (!s) return [];
  const out = [];
  for (const [cn, n] of Object.entries(XH_ICON_SEMANTIC)) {
    if (cn.toLowerCase().includes(s) || n.includes(s)) out.push(n);
  }
  for (const [n, zh] of Object.entries(XH_ICON_LABELS)) {
    if (n.includes(s) || zh.toLowerCase().includes(s)) out.push(n);
  }
  return [...new Set(out)].slice(0, limit);
}
